import {texEq as eq,inlineMath} from './math.js';
import {table as baseTable,cite} from './topic-tools.js';
const p=x=>`<p>${x}</p>`;
const table=(caption,headers,rows)=>baseTable(caption,headers,rows).replace('class="dense-table-wrap"',`class="dense-table-wrap" tabindex="0" role="region" aria-label="${caption}"`);
const a100='https://www.nvidia.com/content/dam/en-zz/Solutions/Data-Center/a100/pdf/nvidia-a100-datasheet-us-nvidia-1758950-r4-web.pdf';
export const performanceTrafficRows=()=>[
 ['FP32 y=a+b','1 addition;4+4+4=12 bytes; '+inlineMath(String.raw`I=\frac1{12}`),'Low intensity even with ideal access'],
 ['Poor-reuse matmul','Assigned '+inlineMath('I=0.25')+' FLOP/byte','Large math alone does not establish efficient reuse'],
 ['Ideal square FP16/BF16 GEMM',inlineMath(String.raw`F\approx2N^3,\quad Q=6N^2,\quad I\approx\frac N3`),'One read per input and one output write, beta=0'],
 ['N=4096 ideal square GEMM',inlineMath(String.raw`I\approx\frac{4096}{3}\approx1365`),'About 1,365 FLOP/byte; ideal traffic; finite tiling/cache can reload inputs']
];

// Static explanations remain available without running any interactive scene.
export function performanceReferenceSections(link){return {
 'roofline':p('Operational intensity is another name for arithmetic intensity when the counted byte boundary is the same.')+p('To build a useful roofline, first choose the operation, precision and memory boundary. Then count its FLOPs and boundary-crossing bytes. Obtain matching hardware ceilings, compute intensity, and compare measured performance with the bound.')+table('A roofline suggests a hypothesis, not a proven bottleneck',['Observation','Candidate change','What to verify'],[
  ['Bandwidth ceiling is lower','Reduce traffic; fuse, tile, reuse, coalesce or use a smaller representation','Actual boundary bytes and latency decrease without changing required results'],
  ['Compute ceiling is lower','Use a suitable Tensor Core path, better tiles/instructions or fewer synchronizations','Shapes and precision match; achieved kernels improve, not merely occupancy'],
  ['Measured point is far below both ceilings','Inspect launches, dependencies, instruction mix and hidden traffic','Find the critical path in a representative trace']
 ])+p('cuBLAS, fused kernels and FlashAttention are candidates for their supported operations. They are not interchangeable replacements for arbitrary code. Choose a change that addresses the measured operation and preserve its numerical contract.'),
 'hardware-roofs':p(cite(a100,'NVIDIA’s June 2021 A100 data sheet')+' lists 19.5 TFLOP/s FP32 and 1,555 GB/s HBM bandwidth for the 40 GB PCIe and SXM variants. Dense BF16 Tensor Core peak is 312 TFLOP/s; the 624 value requires sparsity. These are manufacturer ceilings, not achieved measurements.')+eq(String.raw`\begin{aligned}I_{\rm ridge,FP32}&=\frac{19.5\times10^{12}}{1555\times10^9}\approx12.54\\I_{\rm ridge,BF16\ dense}&=\frac{312\times10^{12}}{1555\times10^9}\approx200.64\end{aligned}`,'Both ridges use the 40 GB A100 HBM ceiling and have units FLOP/byte. The compute paths differ. The sheet lists different bandwidths for 80 GB PCIe and SXM; do not reuse this pair for those variants.')+p('Under the weight-dominated BF16 estimate, batch 32 has intensity about 32, below 200.64. It does not cross this BF16 roof. The FP32 ridge cannot justify the opposite conclusion. Extra activation/cache traffic and inefficient kernels can lower achieved performance further.'),
 'utilization':p('MFU=1 means the declared useful-model FLOP rate equals the declared peak. It does not prove that every operation or every calendar interval is efficient.')+table('Declare what the numerator counts',['Work','Useful-model convention here','Effect on the timing window'],[
  ['Leading projection, attention and selected-expert matrix products','Included under the declared architecture convention','Match actual tokens, masks and selected matrices'],
  ['Activation recomputation','Excluded from useful model work; included in the assigned executed-work HFU','Consumes the same measured step interval'],
  ['Elementwise/optimizer work, input delivery, CPU orchestration and synchronization','Outside a leading-matmul numerator unless explicitly added','Their exposed time still belongs to a complete step'],
  ['Checkpoint, startup, failure, replay and recovery','Use a separate calendar-progress boundary','A healthy-step MFU alone does not capture these losses']
 ])+p('Use the same FLOP convention when comparing kernels, parallel layouts or regressions. High GPU-busy percentage can coexist with low useful arithmetic rate. High healthy-step MFU can coexist with poor durable progress. Follow '+`<a href="${link('training/practice#restart')}">run design and restart contracts</a>`+' for the operational checks. <a href="'+link('training/frontier-recipes')+'">Frontier training recipes</a> connect this distinction to the Llama 3 and MAI reports.'),
 'mfu-examples':p('Consider eight devices, each assigned 10¹⁵ FLOP/s peak, and a 0.40 s step. Their available peak work is 3.2×10¹⁵ FLOPs. Keep this denominator fixed while checking the claimed numerator.') +p('The original 1.2×10¹⁶ numerator gives 375%, not 37.5%. A consistent 37.5% example uses 1.2×10¹⁵ model FLOPs. The change is explicit; a ratio above one calls for an input/convention investigation, not clamping.')+eq(String.raw`\begin{aligned}F_{\rm available}&=0.40\times8\times10^{15}=3.2\times10^{15}\\\frac{1.2\times10^{16}}{F_{\rm available}}&=3.75\quad\text{inconsistent original input}\\\frac{1.2\times10^{15}}{F_{\rm available}}&=0.375\quad\text{explicit corrected input}\end{aligned}`,'Favailable is peak FLOPs available during the assigned 0.40-second, eight-device interval. The corrected numerator is ten times smaller; it is not a re-interpretation of the original number.')+eq(String.raw`\begin{aligned}F_{\rm model}&\approx6(7\times10^9)(2\times10^6)=8.4\times10^{16}\\F_{\rm available}&=2.8(64)(10^{15})=1.792\times10^{17}\\\mathrm{MFU}&\approx\frac{8.4\times10^{16}}{1.792\times10^{17}}=0.46875\end{aligned}`,'This assigned 7B/2M-token example uses the 6PT convention, 64 identical devices, 2.8 seconds and 10¹⁵ FLOP/s/device. The original intermediate ratio 8.4/179.2 omitted a factor of ten; the final 46.9% result was correct.')+p('Under these stated conditions, the second example gives about 46.9%. Both examples are assigned arithmetic, not measured training runs.'),
 'capacity':p('For decimal scientific units, thousand, million, billion and trillion mean powers 3, 6, 9 and 12 of ten. PFLOP/s and EFLOP/s mean powers 15 and 18 FLOP/s. Keep intermediate arithmetic unrounded; round the planning result only after cross-checking it.'),
 'worksheet':p('For communication, record collective frequency as well as the largest payload. For memory, measure allocated and reserved peaks separately. For restart, include restore and reconfiguration, then validate the plan with an injected-failure rehearsal. These checks test the assumptions that simple arithmetic cannot establish. The largest uncertainty can be achieved MFU, unique usable data volume, full-scale stability or overlap. Name it and choose a rehearsal that reduces it.')
};}
